inline constexpr PlayerTechnologyTextR2 kPlayerTechnologyTextR2[] = {
    {"fr.tech.0", "\u6b65\u67aa\u5b88\u5907", "\u4ee4\u4e00\u652f\u505c\u9a7b\u7684\u6b65\u67aa\u7ec4\u4fdd\u6301\u9635\u4f4d\uff0c\u6216\u89e3\u9664\u9a7b\u5b88\u540e\u91cd\u65b0\u8c03\u9063\u3002", "\u7559\u4e0b\u7684\u961f\u4f0d\u5360\u636e\u5f53\u524d\u4f4d\u7f6e\uff0c\u6b63\u9762\u53ef\u8c03\u9063\u7684\u5175\u529b\u968f\u4e4b\u51cf\u5c11\u3002"},
    {"fr.tech.1", "\u88c5\u586b\u534f\u8c03", "\u9009\u62e9\u76f4\u63a5\u63d0\u4ea4\u70ae\u706b\u8ba1\u5212\uff0c\u6216\u7b49\u9009\u5b9a\u673a\u67aa\u7ec4\u88c5\u586b\u5b8c\u6bd5\uff0c\u518d\u7559\u51fa2\u79d2\u51c6\u5907\u95f4\u9694\u3002", "\u7b49\u5f85\u671f\u95f4\u89c2\u5bdf\u7ec4\u4ecd\u987b\u4fdd\u6301\u89c6\u7ebf\uff0c\u70ae\u706b\u627f\u8bfa\u968f\u4e4b\u63a8\u8fdf\u3002"},
    {"fr.tech.2", "\u8d70\u5eca\u5206\u706b", "\u56db\u8f6e\u70ae\u51fb\u5168\u90e8\u7528\u4e8e\u63a8\u8fdb\u8d70\u5eca\uff0c\u6216\u4e09\u8f6e\u538b\u4f4f\u8d70\u5eca\u3001\u672b\u8f6e\u5c01\u4f4f\u53cd\u51b2\u8def\u7ebf\u3002", "\u5206\u706b\u4f1a\u51cf\u5c11\u4e00\u8f6e\u524d\u6cbf\u8986\u76d6\uff0c\u53cd\u51b2\u8def\u7ebf\u4e5f\u987b\u7531\u89c2\u5bdf\u7ec4\u770b\u6e05\u3002"},
    {"fr.tech.3", "\u53cc\u6848\u6bd4\u8f83", "\u6bd4\u8f83\u4e24\u5904\u5df2\u6709\u89c2\u5bdf\u7684\u70ae\u51fb\u5730\u6bb5\uff0c\u9009\u62e9\u4e00\u5904\u4f5c\u4e3a\u672c\u6b21\u76ee\u6807\u3002", "\u9700\u4e24\u652f\u89c2\u5bdf\u961f\u8fde\u7eed\u4fdd\u63014\u79d2\u89c6\u7ebf\uff0c\u70ae\u706b\u53ea\u6267\u884c\u9009\u5b9a\u7684\u4e00\u4efd\u8ba1\u5212\u3002"},
    {"fr.tech.4", "\u8ddf\u8fdb\u8282\u594f", "\u5b89\u6392\u4e00\u652f\u7a81\u51fb\u7ec4\u6216\u67aa\u69b4\u5f39\u7ec4\uff0c\u5728\u7b2c\u4e8c\u8f6e\u6216\u672b\u8f6e\u70ae\u51fb\u540e\u8ddf\u8fdb\u3002", "\u63a5\u7eed\u987b\u8d76\u5728\u70ae\u51fb\u540e\u76848\u79d2\u7a97\u53e3\u5185\uff0c\u63d0\u524d\u6295\u5165\u4e5f\u8981\u9762\u5bf9\u6b8b\u4f59\u706b\u529b\u3002"},
    {"fr.tech.5", "\u9635\u5730\u8f6c\u79fb", "\u5c06\u4e00\u652f\u73b0\u6709\u5c0f\u961f\u8c03\u5f80\u53e6\u4e00\u5904\u9635\u5730\uff0c\u91cd\u65b0\u5b89\u6392\u96c6\u5408\u6216\u64a4\u6536\u3002", "\u8f6c\u79fb\u4f1a\u5360\u7528\u8fd9\u652f\u961f\u4f0d\u7684\u884c\u519b\u65f6\u95f4\uff0c\u65b0\u9635\u4f4d\u987b\u6709\u5bb9\u7eb3\u961f\u4f0d\u7684\u7a7a\u4f4d\u3002"},
    {"fr.tech.6", "\u53cc\u961f\u63a5\u7eed", "\u70ae\u706b\u8ba1\u5212\u63d0\u4ea4\u524d\uff0c\u9009\u62e9\u4e00\u652f\u6216\u4e24\u652f\u73b0\u6709\u5c0f\u961f\u627f\u62c5\u8ddf\u8fdb\u3002", "\u4e24\u961f\u6295\u5165\u4f1a\u5360\u7528\u66f4\u591a\u4eba\u624b\uff0c\u8def\u53e3\u5bb9\u91cf\u4e0e\u654c\u519b\u4e89\u593a\u4ecd\u5f71\u54cd\u63a5\u7eed\u3002"},
    {"fr.tech.7", "\u673a\u67aa\u8f6c\u4f4d", "\u628a\u673a\u67aa\u7ec4\u8c03\u5f80\u5c71\u810a\u3001\u540e\u5761\u6216\u53e6\u4e00\u5904\u5c04\u4f4d\uff0c\u91cd\u65b0\u5e03\u7f6e\u652f\u63f4\u3002", "\u8f6c\u79fb\u671f\u95f4\u539f\u5c04\u4f4d\u5931\u53bb\u63a9\u62a4\uff0c\u5230\u4f4d\u540e\u8fd8\u987b\u5b8c\u6210\u67b6\u67aa\u51c6\u5907\u3002"},
    {"fr.tech.8", "\u53cc\u5c97\u62e9\u70b9", "\u6307\u5b9a\u4e24\u652f\u89c2\u5bdf\u961f\u786e\u8ba4\u4e24\u5904\u5730\u6bb5\uff0c\u518d\u9009\u5b9a\u4e00\u5904\u70ae\u51fb\u76ee\u6807\u3002", "\u4e24\u961f\u987b\u8fde\u7eed\u4fdd\u63014\u79d2\u89c6\u7ebf\uff0c\u53e6\u4e00\u5904\u53ea\u4fdd\u7559\u4e3a\u5907\u9009\u76ee\u6807\u3002"},
    {"fr.tech.9", "\u70df\u5e55\u5e03\u7f6e", "\u70df\u5e55\u53ef\u7528\u65f6\uff0c\u9009\u62e9\u63a9\u62a4\u89c2\u5bdf\u7ec4\u9000\u8def\u6216\u6b65\u5175\u63a5\u7eed\u65b9\u5411\u3002", "\u70df\u5e55\u7528\u8fc7\u540e\u8981\u7b49\u4e0b\u6b21\u6574\u5907\uff0c\u8986\u76d6\u65b9\u5411\u987b\u914d\u5408\u961f\u4f0d\u884c\u52a8\u3002"},
    {"fr.tech.10", "\u7f3a\u53e3\u6539\u9009", "\u4e3a\u5de5\u5175\u6539\u9009\u672c\u5173\u5141\u8bb8\u6e05\u7406\u7684\u53e6\u4e00\u5904\u7f3a\u53e3\uff0c\u8c03\u6574\u63a5\u8fd1\u65b9\u5411\u3002", "\u6539\u6362\u7f3a\u53e3\u8981\u91cd\u65b0\u5230\u573a\u5e76\u4ece\u5934\u4f5c\u4e1a\uff0c\u987b\u7559\u8db3\u5b8c\u6574\u6e05\u969c\u65f6\u95f4\u3002"},
    {"fr.tech.11", "\u89c2\u5bdf\u4ea4\u63a5", "\u70ae\u706b\u63d0\u4ea4\u524d\uff0c\u628a\u89c2\u5bdf\u804c\u8d23\u4ea4\u7ed9\u53e6\u4e00\u652f\u5df2\u7ecf\u5230\u4f4d\u7684\u89c2\u5bdf\u961f\u3002", "\u65b0\u89c2\u5bdf\u7ec4\u8981\u91cd\u65b0\u4fdd\u6301\u8fde\u7eed\u89c6\u7ebf\uff0c\u4ea4\u63a5\u4f1a\u63a8\u8fdf\u8ba1\u5212\u63d0\u4ea4\u3002"},
    {"ru.tech.0", "\u9884\u5907\u9a7b\u5b88", "\u8ba9\u505c\u9a7b\u7684\u9884\u5907\u5c0f\u961f\u4fdd\u6301\u9a7b\u5b88\uff0c\u6216\u89e3\u9664\u9a7b\u5b88\u540e\u91cd\u65b0\u8c03\u9063\u3002", "\u540e\u65b9\u7559\u5b88\u5360\u7528\u73b0\u6709\u4eba\u624b\uff1b\u96c6\u7ed3\u6700\u591a\u4fdd\u630130\u79d2\uff0c\u968f\u540e\u6295\u5165\u6216\u89e3\u9664\u9a7b\u5b88\u3002"},
    {"ru.tech.1", "\u88c5\u586b\u540e\u6295\u5165", "\u6ee1\u8db3\u96c6\u7ed3\u6761\u4ef6\u540e\u76f4\u63a5\u6295\u5165\uff0c\u6216\u7b49\u8be5\u68af\u961f\u88c5\u586b\u5b8c\u6bd5\u518d\u51fa\u53d1\u3002", "\u7b49\u5f85\u8ba1\u516530\u79d2\u96c6\u7ed3\u4e0a\u9650\uff0c\u4e24\u961f\u51fa\u53d1\u4ecd\u987b\u4fdd\u6301\u81f3\u5c116\u79d2\u95f4\u9694\u3002"},
    {"ru.tech.2", "\u540c\u8def\u4e0e\u5206\u8def", "\u51fa\u53d1\u524d\u5b89\u6392\u63a5\u8fd1\u65b9\u5411\uff1b\u4e24\u961f\u9f50\u5907\u65f6\uff0c\u53ef\u96c6\u4e2d\u4e00\u8def\u6216\u5206\u5411\u4e24\u5904\u3002", "\u5206\u8def\u9700\u8981\u4e24\u652f\u53ef\u7528\u9884\u5907\u961f\u4e0e\u4e24\u6761\u901a\u8def\uff0c\u5c40\u90e8\u63a9\u62a4\u4e5f\u4f1a\u66f4\u5206\u6563\u3002"},
    {"ru.tech.3", "\u706b\u529b\u63a5\u5e94", "\u4e3a\u5df2\u9009\u5b9a\u7684\u68af\u961f\u65b9\u5411\u5b89\u6392\u4e00\u6b21\u53ef\u7528\u652f\u63f4\uff0c\u63a9\u62a4\u63a5\u7eed\u901a\u8def\u3002", "\u706b\u529b\u987b\u914d\u5408\u5df2\u9009\u6295\u5165\u65b9\u5411\uff0c\u4f7f\u7528\u540e\u8981\u7b49\u5f85\u4e0b\u6b21\u652f\u63f4\u6574\u5907\u3002"},
    {"ru.tech.4", "\u5148\u9063\u6b21\u5e8f", "\u4e24\u961f\u51fa\u53d1\u524d\uff0c\u51b3\u5b9a\u7531\u7a81\u51fb\u7ec4\u5148\u8d70\uff0c\u8fd8\u662f\u7531\u6b65\u67aa\u7ec4\u5148\u8d70\u3002", "\u9700\u4e24\u652f\u9884\u5907\u961f\u53ca\u6240\u9009\u5175\u79cd\uff0c\u540e\u961f\u81f3\u5c11\u665a6\u79d2\u51fa\u53d1\u3002"},
    {"ru.tech.5", "\u96c6\u7ed3\u8f6c\u79fb", "\u628a\u5c1a\u672a\u51fa\u53d1\u7684\u4e00\u652f\u5c0f\u961f\u8c03\u5230\u53e6\u4e00\u5904\u96c6\u5408\u9635\u5730\u3002", "\u8f6c\u79fb\u9700\u8981\u884c\u519b\uff1b\u5b83\u4e0e\u7b2c\u4e8c\u68af\u961f\u6539\u5411\u5171\u7528\u4e00\u6b21\u8c03\u6574\u673a\u4f1a\u3002"},
    {"ru.tech.6", "\u53cc\u961f\u9884\u5907", "\u96c6\u7ed3\u65f6\u9009\u62e9\u4e00\u652f\u6216\u4e24\u652f\u73b0\u6709\u5c0f\u961f\uff0c\u7ec4\u6210\u7eb5\u6df1\u9884\u5907\u68af\u961f\u3002", "\u4e24\u961f\u90fd\u5360\u7528\u540e\u65b9\u4eba\u624b\u4e0e\u9635\u4f4d\uff0c\u5206\u6279\u51fa\u53d1\u4ecd\u987b\u76f8\u9694\u81f3\u5c116\u79d2\u3002"},
    {"ru.tech.7", "\u9a6c\u514b\u6c81\u8f6c\u4f4d", "\u5c06\u9a6c\u514b\u6c81\u7ec4\u8c03\u5f80\u53e6\u4e00\u5904\u5c04\u4f4d\uff0c\u91cd\u65b0\u5b89\u6392\u4e3b\u53e3\u6216\u4fa7\u8def\u63a9\u62a4\u3002", "\u8f6c\u79fb\u65f6\u539f\u5c04\u4f4d\u5931\u53bb\u63a9\u62a4\uff0c\u5230\u4f4d\u540e\u8fd8\u987b\u5b8c\u6210\u67b6\u67aa\u51c6\u5907\u3002"},
    {"ru.tech.8", "\u53cc\u8def\u89c2\u5bdf", "\u5e76\u5217\u6807\u793a\u4e24\u5904\u5df2\u89c2\u5bdf\u7684\u63a5\u8fd1\u70b9\uff0c\u8f85\u52a9\u51b3\u5b9a\u6295\u5165\u65b9\u5411\u3002", "\u4e24\u5904\u90fd\u987b\u6709\u5f53\u524d\u89c2\u5bdf\uff0c\u638c\u63e1\u7684\u4fe1\u606f\u53d6\u51b3\u4e8e\u89c2\u5bdf\u961f\u5230\u4f4d\u60c5\u51b5\u3002"},
    {"ru.tech.9", "\u68af\u961f\u70df\u5e55", "\u5c06\u4e00\u6b21\u53ef\u7528\u70df\u5e55\u6295\u5411\u7b2c\u4e00\u68af\u961f\u6216\u7b2c\u4e8c\u68af\u961f\u7684\u63a5\u8fd1\u65b9\u5411\u3002", "\u672c\u5173\u987b\u5177\u5907\u70df\u5e55\u652f\u63f4\uff0c\u8986\u76d6\u65b9\u5411\u4f1a\u5360\u7528\u8fd9\u6b21\u70df\u5e55\u6574\u5907\u3002"},
    {"ru.tech.10", "\u6e05\u969c\u9009\u53e3", "\u4e3a\u5de5\u5175\u9009\u62e9\u672c\u5173\u5141\u8bb8\u6e05\u7406\u7684\u4e3b\u7f3a\u53e3\u6216\u53e6\u4e00\u5904\u7f3a\u53e3\u3002", "\u6539\u6362\u7f3a\u53e3\u9700\u91cd\u65b0\u5230\u573a\u5b8c\u6574\u4f5c\u4e1a\uff0c\u4e00\u652f\u961f\u4f0d\u4e00\u6b21\u5904\u7406\u4e00\u5904\u3002"},
    {"ru.tech.11", "\u7b2c\u4e8c\u68af\u961f\u6539\u5411", "\u7b2c\u4e00\u961f\u51fa\u53d1\u540e\uff0c\u901a\u4fe1\u7ec4\u5728\u8054\u7edc\u70b9\u65f6\uff0c\u53ef\u4e3a\u5c1a\u672a\u51fa\u53d1\u7684\u7b2c\u4e8c\u961f\u6539\u5b9a\u65b9\u5411\u3002", "\u9700\u4e24\u961f\u4e0e\u5230\u4f4d\u901a\u4fe1\u7ec4\uff1b\u4e0e\u96c6\u7ed3\u8f6c\u79fb\u5171\u7528\u4e00\u6b21\u8c03\u6574\uff0c\u51fa\u53d1\u95f4\u9694\u4ecd\u81f3\u5c116\u79d2\u3002"},
};
